const raw = $json.output ?? $json.text ?? $json.response ?? 'Sorry, I could not generate a recipe this time.';
const chatId = $('Telegram Trigger').first().json.message.chat.id;
const maxLength = 3500; // Keep below Telegram's message length limit.
const text = String(raw).trim();
const chunks = [];
let remaining = text;
while (remaining.length > maxLength) {
  let cut = remaining.lastIndexOf('\n', maxLength);
  if (cut < maxLength * 0.5) cut = remaining.lastIndexOf(' ', maxLength);
  if (cut < maxLength * 0.5) cut = maxLength;
  chunks.push(remaining.slice(0, cut).trim());
  remaining = remaining.slice(cut).trim();
}
if (remaining) chunks.push(remaining);
return chunks.map((chunk, index) => ({ json: { chatId, text: chunk, part: index + 1, totalParts: chunks.length } }));
